import{_ as t,a0 as d,w as o,s as r,ao as l,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 上動態鏈接模組庫 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上動態鏈接模組庫 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上動態鏈接模組庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上動態鏈接模組庫 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220531 How dynamic linking for modular libraries works on Linux","title":"如何在 Linux 上動態鏈接模組庫","tag":"202207","desc":""},"relativePath":"202207/20220531 How dynamic linking for modular libraries works on Linux.md","filePath":"[post].md"}'),c={name:"202207/20220531 How dynamic linking for modular libraries works on Linux.md"};function h(u,s,b,g,k,m){const n=d("Link");return o(),r("div",null,[s[27]||(s[27]=l('<h1 id="如何在-linux-上動態鏈接模組庫" tabindex="-1">如何在 Linux 上動態鏈接模組庫 <a class="header-anchor" href="#如何在-linux-上動態鏈接模組庫" aria-label="Permalink to “如何在 Linux 上動態鏈接模組庫”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/10/182540caie7ldrefflffah.jpg" alt=""></p><blockquote><p>學習如何用動態鏈接庫將多個 C 目標文件結合到一個單個的可執行文件之中。</p></blockquote><p>當使用 C 編程語言編寫一個應用程序時，你的代碼通常有多個源文件代碼。</p><p>最終，這些文件必須被編譯到一個單個的可執行文件之中。你可以通過創建靜態或動態庫（後者也被稱為 <ruby>共享<rt>shared</rt></ruby> 庫）來實現這一點。這兩種類型的庫在創建和鏈接的方式上有所不同。兩者都有缺點和優點，這取決於你的使用情況。</p><p>動態鏈接是最常見的方法，尤其是在 Linux 系統上。動態鏈接會保持庫模組化，因此，很多應用程序可以共享一個庫。應用程序的模組化也允許單獨更新其依賴的共享庫。</p><p>在這篇文章中，我將演示動態鏈接是如何工作的。在後期的文章中，我將演示靜態鏈接。</p><h3 id="鏈接器" tabindex="-1">鏈接器 <a class="header-anchor" href="#鏈接器" aria-label="Permalink to “鏈接器”">​</a></h3><p><ruby>鏈接器<rt>linker</rt></ruby>是一個命令，它將一個程序的數個部分結合在一起，併為它們重新組織內存分配。</p><p>鏈接器的功能包括：</p><ul><li>整合一個程序的所有的部分</li><li>計算出一個新的內存組織結構，以便所有的部分組合在一起</li><li>恢復內存地址，以便程序可以在新的內存組織結構下運行</li><li>解析符號引用</li></ul>',11)),i("p",null,[s[1]||(s[1]=a("鏈接器通過這些功能，創建了一個名為",-1)),s[2]||(s[2]=i("ruby",null,[a("可執行文件"),i("rt",null,"executable")],-1)),s[3]||(s[3]=a("的可以運行的程序。在你創建一個動態鏈接的可執行文件前，你需要一些用來鏈接的庫，和一個用來編譯的應用程序。準備好你 ",-1)),e(n,{href:"https://opensource.com/article/21/2/open-source-text-editors"},{default:p(()=>[...s[0]||(s[0]=[a("最喜歡的文本編輯器",-1)])]),_:1}),s[4]||(s[4]=a(" 並繼續。",-1))]),s[28]||(s[28]=l(`<h3 id="創建目標文件" tabindex="-1">創建目標文件 <a class="header-anchor" href="#創建目標文件" aria-label="Permalink to “創建目標文件”">​</a></h3><p>首先，創建帶有這些函數簽名的頭文件 <code>mymath.h</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int sub(int a, int b);</span></span>
<span class="line"><span>int mult(int a, int b);</span></span>
<span class="line"><span>int divi(int a, int b);</span></span></code></pre></div><p>使用這些函數定義來創建 <code>add.c</code> 、<code>sub.c</code> 、<code>mult.c</code> 和 <code>divi.c</code> 文件。我將把所有的代碼都放置到一個代碼塊中，請將其分為四個文件，如註釋所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// add.c</span></span>
<span class="line"><span>int add(int a, int b){</span></span>
<span class="line"><span>return (a+b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//sub.c</span></span>
<span class="line"><span>int sub(int a, int b){</span></span>
<span class="line"><span>return (a-b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//mult.c</span></span>
<span class="line"><span>int mult(int a, int b){</span></span>
<span class="line"><span>return (a*b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//divi.c</span></span>
<span class="line"><span>int divi(int a, int b){</span></span>
<span class="line"><span>return (a/b);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>現在，使用 GCC 來創建目標文件 <code>add.o</code>、<code>sub.o</code>、<code>mult.o</code> 和 <code>divi.o</code> ：</p><p>（LCTT 校注：關於“<ruby>目標文件<rt>object file</rt></ruby>”，有時候也被稱作“對象文件”，對此，存在一些譯法混亂情形，稱之為“目標文件”的譯法比較流行，本文采用此譯法。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -c add.c sub.c mult.c divi.c</span></span></code></pre></div><p><code>-c</code> 選項跳過鏈接步驟，並且只創建目標文件。</p><h3 id="創建一個共享的目標文件" tabindex="-1">創建一個共享的目標文件 <a class="header-anchor" href="#創建一個共享的目標文件" aria-label="Permalink to “創建一個共享的目標文件”">​</a></h3><p>在最終的可執行文件的執行過程中將鏈接動態庫。在最終的可執行文件中僅放置動態庫的名稱。實際上的鏈接過程發生在運行時，在此期間，可執行文件和庫都被放置到了主內存中。</p><p>除了可共享外，動態庫的另外一個優點是它減少了最終的可執行文件的大小。在一個應用程序最終的可執行文件生成時，其使用的庫只包括該庫的名稱，而不是該庫的一個多餘的副本。</p><p>你可以從你現有的示例代碼中創建動態庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -Wall -fPIC -c add.c sub.c mult.c divi.c</span></span></code></pre></div><p>選項 <code>-fPIC</code> 告訴 GCC 來生成<ruby>位置無關的代碼<rt>position-independent code</rt></ruby>（PIC）。<code>-Wall</code> 選項不是必需的，並且與代碼的編譯方式是無關的。不過，它卻是一個有價值的選項，因為它會啓用編譯器警告，這在排除故障時是很有幫助的。</p><p>使用 GCC ，創建共享庫 <code>libmymath.so</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -shared -o libmymath.so add.o sub.o mult.o divi.o</span></span></code></pre></div><p>現在，你已經創建了一個簡單的示例數學庫 <code>libmymath.so</code> ，你可以在 C 代碼中使用它。當然，也有非常複雜的 C 庫，這就是他們這些開發者來生成最終產品的工藝流程，你和我可以安裝這些庫並在 C 代碼中使用。</p><p>接下來，你可以在一些自定義代碼中使用你的新數學庫，然後鏈接它。</p><h3 id="創建一個動態鏈接的可執行文件" tabindex="-1">創建一個動態鏈接的可執行文件 <a class="header-anchor" href="#創建一個動態鏈接的可執行文件" aria-label="Permalink to “創建一個動態鏈接的可執行文件”">​</a></h3><p>假設你已經為數學運算編寫了一個命令。創建一個名稱為 <code>mathDemo.c</code> 的文件，並將這些代碼複製粘貼至其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;mymath.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  int x, y;</span></span>
<span class="line"><span>  printf(&quot;Enter two numbers\\n&quot;);</span></span>
<span class="line"><span>  scanf(&quot;%d%d&quot;,&amp;x,&amp;y);</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>  printf(&quot;\\n%d + %d = %d&quot;, x, y, add(x, y));</span></span>
<span class="line"><span>  printf(&quot;\\n%d - %d = %d&quot;, x, y, sub(x, y));</span></span>
<span class="line"><span>  printf(&quot;\\n%d * %d = %d&quot;, x, y, mult(x, y));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  if(y==0){</span></span>
<span class="line"><span>    printf(&quot;\\nDenominator is zero so can&#39;t perform division\\n&quot;);</span></span>
<span class="line"><span>      exit(0);</span></span>
<span class="line"><span>  }else{</span></span>
<span class="line"><span>      printf(&quot;\\n%d / %d = %d\\n&quot;, x, y, divi(x, y));</span></span>
<span class="line"><span>      return 0;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,22)),i("p",null,[s[6]||(s[6]=a("注意：第一行是一個 ",-1)),s[7]||(s[7]=i("code",null,"include",-1)),s[8]||(s[8]=a(" 語句，通過名稱來引用你自己的 ",-1)),s[9]||(s[9]=i("code",null,"libmymath",-1)),s[10]||(s[10]=a(" 庫。要使用一個共享庫，你必須已經安裝了它，如果你沒有安裝你將要使用的庫，那麼當你的可執行文件在運行並搜索其包含的庫時，將找不到該共享庫。如果你需要在不安裝庫到已知目錄的情況下編譯代碼，這裏有 ",-1)),e(n,{href:"https://opensource.com/article/22/5/compile-code-ldlibrarypath"},{default:p(()=>[...s[5]||(s[5]=[a("一些方法可以覆蓋默認設置",-1)])]),_:1}),s[11]||(s[11]=a("。不過，對於一般使用來説，我們希望庫存在於已知的位置，因此，這就是我在這裏演示的東西。",-1))]),s[29]||(s[29]=l(`<p>複製文件 <code>libmymath.so</code> 到一個標準的系統目錄，例如：<code>/usr/lib64</code>， 然後運行 <code>ldconfig</code> 。<code>ldconfig</code> 命令創建所需的鏈接，並緩存到標準庫目錄中發現的最新共享庫。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp libmymath.so /usr/lib64/</span></span>
<span class="line"><span>$ sudo ldconfig</span></span></code></pre></div><h3 id="編譯應用程序" tabindex="-1">編譯應用程序 <a class="header-anchor" href="#編譯應用程序" aria-label="Permalink to “編譯應用程序”">​</a></h3><p>從你的應用程序源文件代碼（<code>mathDemo.c</code>）中創建一個名稱為 <code>mathDemo.o</code> 的目標文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -I . -c mathDemo.c</span></span></code></pre></div><p><code>-I</code> 選項告訴 GCC 來在其後所列出的目錄中搜索頭文件（在這個示例中是 <code>mymath.h</code>）。在這個示例中，你指定的是當前目錄，通過一個單點（<code>.</code>）來表示。創建一個可執行文件，使用 <code>-l</code> 選項來通過名稱來引用你的共享數學庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -o mathDynamic mathDemo.o -lmymath</span></span></code></pre></div><p>GCC 會找到 <code>libmymath.so</code> ，因為它存在於一個默認的系統庫目錄中。使用 <code>ldd</code> 來查證所使用的共享庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ldd mathDemo</span></span>
<span class="line"><span>    linux-vdso.so.1 (0x00007fffe6a30000)</span></span>
<span class="line"><span>    libmymath.so =&gt; /usr/lib64/libmymath.so (0x00007fe4d4d33000)</span></span>
<span class="line"><span>    libc.so.6 =&gt; /lib64/libc.so.6 (0x00007fe4d4b29000)</span></span>
<span class="line"><span>    /lib64/ld-linux-x86-64.so.2 (0x00007fe4d4d4e000)</span></span></code></pre></div><p>看看 <code>mathDemo</code> 可執行文件的大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du ./mathDynamic</span></span>
<span class="line"><span>24   ./mathDynamic</span></span></code></pre></div><p>當然，它是一個小的應用程序，它所佔用的磁盤空間量也反映了這一點。相比之下，相同代碼的一個靜態鏈接版本（正如你將在我後期的文章所看到的一樣）是 932K !</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./mathDynamic</span></span>
<span class="line"><span>Enter two numbers</span></span>
<span class="line"><span>25</span></span>
<span class="line"><span>5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>25 + 5 = 30</span></span>
<span class="line"><span>25 - 5 = 20</span></span>
<span class="line"><span>25 * 5 = 125</span></span>
<span class="line"><span>25 / 5 = 5</span></span></code></pre></div><p>你可以使用 <code>file</code> 命令來查證它是動態鏈接的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file ./mathDynamic</span></span>
<span class="line"><span>./mathDynamic: ELF 64-bit LSB executable, x86-64,</span></span>
<span class="line"><span>dynamically linked,</span></span>
<span class="line"><span>interpreter /lib64/ld-linux-x86-64.so.2,</span></span>
<span class="line"><span>with debug_info, not stripped</span></span></code></pre></div><p>成功！</p><h3 id="動態鏈接" tabindex="-1">動態鏈接 <a class="header-anchor" href="#動態鏈接" aria-label="Permalink to “動態鏈接”">​</a></h3><p>因為鏈接發生在運行時，所以，使用一個共享庫會產生一個輕量型的可執行文件。因為它在運行時解析引用，所以它會花費更多的執行時間。不過，因為在日常使用的 Linux 系統上絕大多數的命令是動態鏈接的，並且在現代硬件上，所能節省的時間是可以忽略不計的。對開發者和用户來説，它的固有模組性是一種強大的功能。</p><p>在這篇文章中，我描述瞭如何創建動態庫，並將其鏈接到一個最終可執行文件。在我的下一篇文章中，我將使用相同的源文件代碼來創建一個靜態鏈接的可執行文件。</p><hr>`,20)),i("p",null,[s[13]||(s[13]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/22/5/dynamic-linking-modular-libraries-linux"},{default:p(()=>[...s[12]||(s[12]=[a("https://opensource.com/article/22/5/dynamic-linking-modular-libraries-linux",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jayashree-huttanagoudar"},{default:p(()=>[...s[14]||(s[14]=[a("Jayashree Huttanagoudar",-1)])]),_:1}),s[19]||(s[19]=a(" 選題：",-1)),e(n,{href:"https://github.com/lkxed"},{default:p(()=>[...s[15]||(s[15]=[a("lkxed",-1)])]),_:1}),s[20]||(s[20]=a(" 譯者：",-1)),e(n,{href:"https://github.com/robsean"},{default:p(()=>[...s[16]||(s[16]=[a("robsean",-1)])]),_:1}),s[21]||(s[21]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[17]||(s[17]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[24]||(s[24]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[22]||(s[22]=[a("LCTT",-1)])]),_:1}),s[25]||(s[25]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[23]||(s[23]=[a("Linux中國",-1)])]),_:1}),s[26]||(s[26]=a(" 榮譽推出",-1))])])}const C=t(c,[["render",h]]);export{x as __pageData,C as default};
